const apiBase = localStorage.getItem('locapro_api_url') || 'http://localhost:3000/api';
const state = { equipment: [
  { id: 1, name: 'Escavadeira hidráulica', type: 'Linha amarela', dailyRate: 1850, status: 'rented' },
  { id: 2, name: 'Compactador de solo', type: 'Compactação', dailyRate: 720, status: 'available' },
  { id: 3, name: 'Gerador 150 kVA', type: 'Energia', dailyRate: 540, status: 'available' },
  { id: 4, name: 'Betoneira 400 L', type: 'Concretagem', dailyRate: 260, status: 'rented' },
  { id: 5, name: 'Plataforma elevatória', type: 'Elevação', dailyRate: 890, status: 'available' },
  { id: 6, name: 'Caminhão basculante', type: 'Transporte', dailyRate: 1200, status: 'available' }
], rentals: [
  { id: 101, equipmentId: 1, startDate: '2026-11-17', expectedReturnDate: '2026-12-05', status: 'active' },
  { id: 102, equipmentId: 4, startDate: '2026-11-19', expectedReturnDate: '2026-11-26', status: 'active' }
], returns: [{ id: 203, equipmentId: 3, rentalId: 98, returnDate: '2026-11-16', condition: 'Ótimo estado', notes: 'Higienizado e revisado.' }] };
const $ = (selector) => document.querySelector(selector);
const fmtMoney = (v) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
const fmtDate = (value) => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${value}T12:00:00`));
const equipmentName = (id) => state.equipment.find(e => e.id === Number(id))?.name || 'Equipamento removido';
function renderDashboard(){const total=state.equipment.length, available=state.equipment.filter(e=>e.status==='available').length, rented=total-available, pct=total?Math.round(available/total*100):0;$('#total-equipment').textContent=total;$('#available-equipment').textContent=available;$('#active-rentals').textContent=rented;$('#occupancy').textContent=`${total?Math.round(rented/total*100):0}%`;$('#ring-value').textContent=`${pct}%`;$('.ring').style.setProperty('--percentage',`${pct}%`);$('#available-legend').textContent=available;$('#rented-legend').textContent=rented;$('#activity-list').innerHTML=[...state.rentals.filter(r=>r.status==='active').map(r=>({icon:'◫',title:'Locação em andamento',body:equipmentName(r.equipmentId),time:`até ${fmtDate(r.expectedReturnDate)}`})),...state.returns.map(r=>({icon:'↙',title:'Devolução registrada',body:equipmentName(r.equipmentId),time:fmtDate(r.returnDate)}))].slice(0,4).map(a=>`<div class="activity"><div class="activity-icon">${a.icon}</div><div class="detail"><strong>${a.title}</strong><small>${a.body}</small></div><time>${a.time}</time></div>`).join('');}
function renderEquipment(filter=''){const icons=['⌁','◉','⚡','◍','↥','▰'];const list=state.equipment.filter(e=>`${e.name} ${e.type}`.toLowerCase().includes(filter.toLowerCase()));$('#equipment-grid').innerHTML=list.map((e,i)=>`<article class="equipment-card"><div class="equipment-top"><div class="equipment-icon">${icons[i%icons.length]}</div><span class="badge ${e.status}">${e.status==='available'?'DISPONÍVEL':'EM LOCAÇÃO'}</span></div><h3>${e.name}</h3><p>${e.type}</p><div class="equipment-foot"><span>Diária</span><strong>${fmtMoney(e.dailyRate)}</strong></div></article>`).join('') || '<p>Nenhum equipamento encontrado.</p>'}
function renderRentals(){$('#rentals-table').innerHTML=state.rentals.map(r=>`<tr><td class="row-name"><strong>${equipmentName(r.equipmentId)}</strong><small>Contrato #${r.id}</small></td><td>${fmtDate(r.startDate)}</td><td>${fmtDate(r.expectedReturnDate)}</td><td><span class="badge ${r.status==='active'?'rented':'available'}">${r.status==='active'?'ATIVA':'DEVOLVIDA'}</span></td><td>${r.status==='active'?`<button class="link-button return-button" data-id="${r.id}">Registrar devolução</button>`:''}</td></tr>`).join('')}
function renderReturns(){$('#returns-list').innerHTML=state.returns.map(r=>`<article class="return-card"><span>↙</span><p><strong>${equipmentName(r.equipmentId)}</strong><br><small>${r.condition}${r.notes?' · '+r.notes:''}</small></p><time>${fmtDate(r.returnDate)}</time></article>`).join('') || '<p>Sem devoluções registradas.</p>'}
function renderAll(){renderDashboard();renderEquipment($('#equipment-search')?.value||'');renderRentals();renderReturns()}
function navigate(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={dashboard:'Visão geral',equipment:'Equipamentos',rentals:'Locações',returns:'Devoluções'};$('#page-title').textContent=labels[view];$('#quick-action').style.display=view==='equipment'?'none':'';window.location.hash=view}
function notify(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function field(label,name,type='text',options=''){return `<label>${label}${options?`<select name="${name}" required autocomplete="off">${options}</select>`:`<input name="${name}" type="${type}" required autocomplete="off" />`}</label>`}
function openEquipmentModal(){$('#modal-title').textContent='Cadastrar equipamento';$('#modal-fields').innerHTML=field('Nome','name')+field('Tipo','type')+field('Valor da diária (R$)','dailyRate','number');$('#modal').dataset.mode='equipment';$('#modal').showModal()}
function openRentalModal(){$('#modal-title').textContent='Nova locação';const options=state.equipment.filter(e=>e.status==='available').map(e=>`<option value="${e.id}">${e.name}</option>`).join('');if(!options)return notify('Não há equipamentos disponíveis para locação.');$('#modal-fields').innerHTML=field('Equipamento','equipmentId','text',options)+field('Data de início','startDate','date')+field('Devolução prevista','expectedReturnDate','date');$('#modal').dataset.mode='rental';$('#modal').showModal()}
function openReturnModal(id){const rental=state.rentals.find(r=>r.id===Number(id));$('#modal-title').textContent='Registrar devolução';$('#modal-fields').innerHTML=`<p><strong>${equipmentName(rental.equipmentId)}</strong><br><small>Contrato #${rental.id}</small></p>`+field('Data da devolução','returnDate','date')+field('Condição','condition','text')+`<label>Observações<input name="notes" /></label>`;$('#modal').dataset.mode='return';$('#modal').dataset.rentalId=id;$('#modal').showModal()}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.querySelectorAll('[data-view-target]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.viewTarget)));$('#quick-action').addEventListener('click',openEquipmentModal);$('#add-equipment').addEventListener('click',openEquipmentModal);$('#new-rental').addEventListener('click',openRentalModal);$('#equipment-search').addEventListener('input',e=>renderEquipment(e.target.value));$('#rentals-table').addEventListener('click',e=>{if(e.target.matches('.return-button'))openReturnModal(e.target.dataset.id)});$('#logout').addEventListener('click',()=>notify('Sessão demonstrativa encerrada.'));$('#modal-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const mode=$('#modal').dataset.mode;if(mode==='equipment'){state.equipment.push({id:Date.now(),...data,dailyRate:Number(data.dailyRate),status:'available'});notify('Equipamento cadastrado com sucesso.')}if(mode==='rental'){const equipment=state.equipment.find(x=>x.id===Number(data.equipmentId));equipment.status='rented';state.rentals.unshift({id:Math.floor(Math.random()*900+100),...data,equipmentId:Number(data.equipmentId),status:'active'});notify('Locação registrada com sucesso.')}if(mode==='return'){const rental=state.rentals.find(r=>r.id===Number($('#modal').dataset.rentalId));rental.status='returned';state.equipment.find(e=>e.id===rental.equipmentId).status='available';state.returns.unshift({id:Date.now(),rentalId:rental.id,equipmentId:rental.equipmentId,...data});notify('Devolução registrada com sucesso.')}$('#modal').close();renderAll()});$('#date-label').textContent=`OPERAÇÃO · ${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date()).toUpperCase()}`;renderAll();navigate(location.hash.slice(1)||'dashboard');
